package com.tekwatt.invoice.entity;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;import java.util.UUID;
@Entity @Table(name="invoices")public class Invoice{@Id private UUID id;@Column(nullable=false)private UUID tenantId;@Column(nullable=false)private UUID userId;@Column(nullable=false,unique=true)private UUID billId;@Column(nullable=false,unique=true,length=50)private String invoiceNumber;@Column(nullable=false,length=150)private String customerName;@Column(nullable=false,length=254)private String customerEmail;@Column(length=1000)private String billingAddress;@Column(length=50)private String taxRegistrationNumber;@Column(nullable=false,precision=12,scale=2)private BigDecimal subtotal;@Column(nullable=false,precision=12,scale=2)private BigDecimal taxAmount;@Column(nullable=false,precision=12,scale=2)private BigDecimal totalAmount;@Column(nullable=false,length=3)private String currency;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private InvoiceStatus status;@Column(nullable=false)private LocalDate issueDate;@Column(nullable=false)private LocalDate dueDate;private Instant issuedAt;private Instant paidAt;@Column(nullable=false,updatable=false)private Instant createdAt;@Column(nullable=false)private Instant updatedAt;protected Invoice(){}public Invoice(UUID t,UUID u,UUID b,String number,String name,String email,String address,String tax,BigDecimal sub,BigDecimal taxAmt,BigDecimal total,String cur,LocalDate issue,LocalDate due){id=UUID.randomUUID();tenantId=t;userId=u;billId=b;invoiceNumber=number;customerName=name;customerEmail=email;billingAddress=address;taxRegistrationNumber=tax;subtotal=sub;taxAmount=taxAmt;totalAmount=total;currency=cur.toUpperCase();issueDate=issue;dueDate=due;status=InvoiceStatus.DRAFT;createdAt=Instant.now();updatedAt=createdAt;}public void issue(){status=InvoiceStatus.ISSUED;issuedAt=Instant.now();updatedAt=issuedAt;}public void pay(){status=InvoiceStatus.PAID;paidAt=Instant.now();updatedAt=paidAt;}public void voidInvoice(){status=InvoiceStatus.VOID;updatedAt=Instant.now();}public void markOverdue(){if(status==InvoiceStatus.ISSUED&&dueDate.isBefore(LocalDate.now())){status=InvoiceStatus.OVERDUE;updatedAt=Instant.now();}}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public UUID getUserId(){return userId;}public UUID getBillId(){return billId;}public String getInvoiceNumber(){return invoiceNumber;}public String getCustomerName(){return customerName;}public String getCustomerEmail(){return customerEmail;}public String getBillingAddress(){return billingAddress;}public String getTaxRegistrationNumber(){return taxRegistrationNumber;}public BigDecimal getSubtotal(){return subtotal;}public BigDecimal getTaxAmount(){return taxAmount;}public BigDecimal getTotalAmount(){return totalAmount;}public String getCurrency(){return currency;}public InvoiceStatus getStatus(){return status;}public LocalDate getIssueDate(){return issueDate;}public LocalDate getDueDate(){return dueDate;}public Instant getIssuedAt(){return issuedAt;}public Instant getPaidAt(){return paidAt;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
